import{_ as n,c as a,b as e,o as l}from"./app-C4rACRSl.js";const p={};function i(t,s){return l(),a("div",null,s[0]||(s[0]=[e(`<h1 id="jcmd-jvm-诊断命令行工具" tabindex="-1"><a class="header-anchor" href="#jcmd-jvm-诊断命令行工具"><span>jcmd - JVM 诊断命令行工具</span></a></h1><p>jcmd（JVM Command）是 JDK 7u40 引入的综合诊断命令行工具，提供对 JVM 进行多种诊断操作的能力。它整合了多个诊断工具的功能，可以通过一个统一的接口执行 JVM 诊断、监控和故障排查任务，是 JDK 中功能最全面的诊断命令行工具。</p><h2 id="工具概述" tabindex="-1"><a class="header-anchor" href="#工具概述"><span>工具概述</span></a></h2><p>jcmd 通过 JVM 的诊断命令接口（Diagnostic Command Interface）与目标 JVM 进程通信，支持执行预定义的诊断命令、获取系统属性、查看线程堆栈、生成堆转储、执行 GC 等操作。相比单独的诊断工具，jcmd 提供了更统一、更可靠的诊断能力。</p><p><strong>工具特点</strong>：</p><ul><li>功能全面：整合多种诊断功能于一身</li><li>稳定性高：使用 JVM 官方诊断接口</li><li>远程支持：支持诊断远程 JVM 进程</li><li>扩展性强：支持自定义诊断命令</li></ul><p><strong>主要用途</strong>：</p><ul><li>执行 JVM 诊断命令</li><li>生成线程堆栈和堆转储</li><li>查看和修改 JVM 选项</li><li>监控系统性能指标</li><li>执行垃圾回收</li><li>导出诊断信息</li></ul><h2 id="安装与基本使用" tabindex="-1"><a class="header-anchor" href="#安装与基本使用"><span>安装与基本使用</span></a></h2><h3 id="环境要求" tabindex="-1"><a class="header-anchor" href="#环境要求"><span>环境要求</span></a></h3><p>jcmd 随 JDK 7u40 及以后版本提供，确保环境变量中配置了 <code>JAVA_HOME</code>。</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 验证 jcmd 是否可用</span></span>
<span class="line">jcmd -?</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查看 JDK 版本</span></span>
<span class="line"><span class="token function">java</span> <span class="token parameter variable">-version</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 列出所有 JVM 进程</span></span>
<span class="line">jcmd <span class="token parameter variable">-l</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="基本语法" tabindex="-1"><a class="header-anchor" href="#基本语法"><span>基本语法</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">jcmd <span class="token punctuation">[</span>options<span class="token punctuation">]</span> <span class="token operator">&lt;</span>pid <span class="token operator">|</span> main class<span class="token operator">&gt;</span> <span class="token operator">&lt;</span>command<span class="token operator">&gt;</span> <span class="token punctuation">[</span>arguments<span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查看可用诊断命令</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>pid<span class="token operator">&gt;</span> <span class="token builtin class-name">help</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查看特定命令的帮助</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>pid<span class="token operator">&gt;</span> <span class="token builtin class-name">help</span> <span class="token operator">&lt;</span>command<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="快速入门示例" tabindex="-1"><a class="header-anchor" href="#快速入门示例"><span>快速入门示例</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 列出所有 Java 进程</span></span>
<span class="line">jcmd <span class="token parameter variable">-l</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查看进程可用的诊断命令</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token builtin class-name">help</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成线程堆栈</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> Thread.print</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成堆转储</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.heap_dump <span class="token assign-left variable">filename</span><span class="token operator">=</span>heapdump.hprof</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查看 JVM 系统属性</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.system_properties</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 执行 Full GC</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.run</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="核心诊断命令详解" tabindex="-1"><a class="header-anchor" href="#核心诊断命令详解"><span>核心诊断命令详解</span></a></h2><h3 id="_1-线程分析命令" tabindex="-1"><a class="header-anchor" href="#_1-线程分析命令"><span>1. 线程分析命令</span></a></h3><h4 id="thread-print-生成线程堆栈" tabindex="-1"><a class="header-anchor" href="#thread-print-生成线程堆栈"><span>Thread.print - 生成线程堆栈</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 基本用法</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> Thread.print</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 输出到文件</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> Thread.print <span class="token operator">&gt;</span> threaddump.txt</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 带锁信息</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> Thread.print <span class="token parameter variable">-l</span><span class="token operator">=</span>true</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>输出示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">2024-12-15 14:30:22</span>
<span class="line">Full thread dump Java HotSpot(TM) 64-Bit Server VM (25.271-b09 mixed mode):</span>
<span class="line"></span>
<span class="line">&quot;main&quot; #1 prio=5 os_prio=0 tid=0x00007f8a4c001000 nid=0x7f8a runnable [0x00007f8a5f7f7000]</span>
<span class="line">   java.lang.Thread.State: RUNNABLE</span>
<span class="line">        at java.lang.Object.hashCode(Native Method)</span>
<span class="line">        at java.lang.Object.equals(Object.java:122)</span>
<span class="line">        at com.example.Main.main(Main.java:15)</span>
<span class="line"></span>
<span class="line">&quot;Reference Handler&quot; #2 daemon prio=10 os_prio=0 tid=0x00007f8a4c01e000 nid=0x7f8b in Object.wait() [0x00007f8a5f6f6000]</span>
<span class="line">   java.lang.Thread.State: WAITING (parking)</span>
<span class="line">        at java.lang.Object.wait(Native Method)</span>
<span class="line">        at java.lang.ref.ReferenceHandler$Lock.wait(BaseModule$2AccessorImpl.java:85)</span>
<span class="line">        - locked &lt;0x00000000c0001234&gt; (a java.lang.Object)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>参数选项</strong>：</p><table><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><code>-l=true</code></td><td>显示锁的详细信息</td></tr><tr><td><code>-e=true</code></td><td>显示线程执行时间信息</td></tr></tbody></table><h3 id="_2-堆内存管理命令" tabindex="-1"><a class="header-anchor" href="#_2-堆内存管理命令"><span>2. 堆内存管理命令</span></a></h3><h4 id="gc-heap-dump-生成堆转储" tabindex="-1"><a class="header-anchor" href="#gc-heap-dump-生成堆转储"><span>GC.heap_dump - 生成堆转储</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 基本用法</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.heap_dump <span class="token assign-left variable">filename</span><span class="token operator">=</span>heapdump.hprof</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>重要说明</strong>：</p><ul><li>GC.heap_dump 会转储当前堆内存中的所有对象</li><li>对于内存使用分析，建议使用 <code>jmap -dump:live</code> 来转储存活对象</li></ul><h4 id="gc-heap-info-查看堆信息" tabindex="-1"><a class="header-anchor" href="#gc-heap-info-查看堆信息"><span>GC.heap_info - 查看堆信息</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看堆内存使用情况</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.heap_info</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>输出示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line"> PSYoungGen      total 75776K, used 1300K [0x00000000f1700000, 0x00000000f6b80000, 0x0000000100000000)</span>
<span class="line">  eden space 65024K, 2% used [0x00000000f1700000,0x00000000f1845200,0x00000000f5680000)</span>
<span class="line">  from space 10752K, 0% used [0x00000000f5680000,0x00000000f5680000,0x00000000f6100000)</span>
<span class="line">  to   space 10752K, 0% used [0x00000000f6100000,0x00000000f6100000,0x00000000f6b80000)</span>
<span class="line"> ParOldGen       total 166400K, used 11998K [0x00000000d4400000, 0x00000000de680000, 0x00000000f1700000)</span>
<span class="line">  object space 166400K, 7% used [0x00000000d4400000,0x00000000d4fb7b00,0x00000000de680000)</span>
<span class="line"> Metaspace       used 22039K, capacity 22385K, committed 22912K, reserved 1069056K</span>
<span class="line">  class space    used 2422K, capacity 2538K, committed 2688K, reserved 1048576K</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="gc-run-执行垃圾回收" tabindex="-1"><a class="header-anchor" href="#gc-run-执行垃圾回收"><span>GC.run - 执行垃圾回收</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 执行 Full GC</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.run</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>使用场景</strong>：</p><ul><li>排查内存泄漏时触发 GC</li><li>测试 GC 行为</li><li>内存压力测试</li></ul><h3 id="_3-gc-诊断命令" tabindex="-1"><a class="header-anchor" href="#_3-gc-诊断命令"><span>3. GC 诊断命令</span></a></h3><h4 id="gc-class-histogram-对象直方图" tabindex="-1"><a class="header-anchor" href="#gc-class-histogram-对象直方图"><span>GC.class_histogram - 对象直方图</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看对象统计</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.class_histogram</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 输出到文件</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.class_histogram <span class="token operator">&gt;</span> histo.txt</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 只统计存活对象</span></span>
<span class="line"><span class="token comment"># Linux/macOS</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.class_histogram <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">100</span> <span class="token string">&quot;Class histogram&quot;</span></span>
<span class="line"><span class="token comment"># Windows PowerShell 等效方案</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.class_histogram <span class="token operator">|</span> Select-String <span class="token string">&quot;Class histogram&quot;</span> <span class="token parameter variable">-Context</span> <span class="token number">0,100</span></span>
<span class="line"><span class="token comment"># Windows cmd 等效方案</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.class_histogram <span class="token operator">|</span> findstr /R <span class="token string">&quot;Class histogram&quot;</span> <span class="token parameter variable">-A</span> <span class="token number">100</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>输出示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line"> num     #instances         #bytes  class name</span>
<span class="line">----------------------------------------------</span>
<span class="line">   1:          45678      3456789  [Ljava.lang.Object;</span>
<span class="line">   2:          23456      1876543  java.lang.String</span>
<span class="line">   3:          12345      1234567  [C</span>
<span class="line">   4:           8765       987654  java.util.HashMap$Node</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="gc-finalizer-info-finalizer-信息" tabindex="-1"><a class="header-anchor" href="#gc-finalizer-info-finalizer-信息"><span>GC.finalizer_info - Finalizer 信息</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看 Finalizer 队列信息</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.finalizer_info</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-vm-系统信息命令" tabindex="-1"><a class="header-anchor" href="#_4-vm-系统信息命令"><span>4. VM 系统信息命令</span></a></h3><h4 id="vm-system-properties-查看系统属性" tabindex="-1"><a class="header-anchor" href="#vm-system-properties-查看系统属性"><span>VM.system_properties - 查看系统属性</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看所有系统属性</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.system_properties</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 过滤特定属性</span></span>
<span class="line"><span class="token comment"># Linux/macOS</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.system_properties <span class="token operator">|</span> <span class="token function">grep</span> <span class="token function">java</span></span>
<span class="line"><span class="token comment"># Windows PowerShell 等效方案</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.system_properties <span class="token operator">|</span> Select-String <span class="token string">&quot;java&quot;</span></span>
<span class="line"><span class="token comment"># Windows cmd 等效方案</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.system_properties <span class="token operator">|</span> findstr /R <span class="token string">&quot;java&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>输出示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">java.runtime.name = OpenJDK Runtime Environment</span>
<span class="line">java.vm.name = OpenJDK 64-Bit Server VM</span>
<span class="line">java.library.path = /usr/lib/jvm/java-17-openjdk-amd64/lib</span>
<span class="line">file.encoding = UTF-8</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="vm-version-查看-jvm-版本" tabindex="-1"><a class="header-anchor" href="#vm-version-查看-jvm-版本"><span>VM.version - 查看 JVM 版本</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看 JVM 版本信息</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.version</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>输出示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">OpenJDK Runtime Environment (Zulu 17.0.9+11-CA) (build 17.0.9+11)</span>
<span class="line">OpenJDK 64-Bit Server VM (build 25.271-b09, mixed mode)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="vm-flags-查看-jvm-参数" tabindex="-1"><a class="header-anchor" href="#vm-flags-查看-jvm-参数"><span>VM.flags - 查看 JVM 参数</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看当前 JVM 参数</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.flags</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 显示修改后的参数</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.flags <span class="token parameter variable">-modified</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>输出示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">-XX:CICompilerCount=4 -XX:InitialHeapSize=266338304 -XX:MaxHeapSize=734003200 -XX:MaxNewSize=244318208 -XX:MinHeapDeltaBytes=524288 -XX:NewSize=88604672 -XX:OldSize=177733632 -XX:+UseCompressedClassPointers -XX:+UseCompressedOops -XX:+UseFastUnorderedTimeStamps -XX:-UseLargePagesIndividualAllocation -XX:+UseParallelGC</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="vm-command-line-查看命令行参数" tabindex="-1"><a class="header-anchor" href="#vm-command-line-查看命令行参数"><span>VM.command_line - 查看命令行参数</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看 JVM 启动命令行</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.command_line</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>输出示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">VM Arguments:</span>
<span class="line">java_command: com.example.Application</span>
<span class="line">java_class_path: /data/app.jar</span>
<span class="line">Launcher Type: SUN_STANDARD</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-性能监控命令" tabindex="-1"><a class="header-anchor" href="#_5-性能监控命令"><span>5. 性能监控命令</span></a></h3><h4 id="perfcounter-print-性能计数器" tabindex="-1"><a class="header-anchor" href="#perfcounter-print-性能计数器"><span>PerfCounter.print - 性能计数器</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看所有性能计数器</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> PerfCounter.print</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 监控特定计数器</span></span>
<span class="line"><span class="token comment"># Linux/macOS</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> PerfCounter.print <span class="token operator">|</span> <span class="token function">grep</span> gc</span>
<span class="line"><span class="token comment"># Windows PowerShell 等效方案</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> PerfCounter.print <span class="token operator">|</span> Select-String <span class="token string">&quot;gc&quot;</span></span>
<span class="line"><span class="token comment"># Windows cmd 等效方案</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> PerfCounter.print <span class="token operator">|</span> findstr /R <span class="token string">&quot;gc&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>常用计数器</strong>：</p><table><thead><tr><th>计数器</th><th>说明</th></tr></thead><tbody><tr><td>java.gc.promotion_failed</td><td>对象晋升失败次数</td></tr><tr><td>java.gc.major_collection_count</td><td>Major GC 次数</td></tr><tr><td>java.gc.minor_collection_count</td><td>Minor GC 次数</td></tr><tr><td>java.threads.started</td><td>启动的线程数</td></tr></tbody></table><h2 id="高级诊断功能" tabindex="-1"><a class="header-anchor" href="#高级诊断功能"><span>高级诊断功能</span></a></h2><h3 id="动态修改-jvm-选项" tabindex="-1"><a class="header-anchor" href="#动态修改-jvm-选项"><span>动态修改 JVM 选项</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看 VM.flags 命令的帮助</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token builtin class-name">help</span> VM.flags</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 修改 PrintGCDetails（如果支持）</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.flags <span class="token assign-left variable">PrintGCDetails</span><span class="token operator">=</span>true</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查看所有可修改的选项</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token builtin class-name">help</span> <span class="token parameter variable">-all</span> VM.flags</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>注意</strong>：并非所有 JVM 选项都支持动态修改。</p><h3 id="诊断命令脚本化" tabindex="-1"><a class="header-anchor" href="#诊断命令脚本化"><span>诊断命令脚本化</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># jcmd-comprehensive-diagnostic.sh - 综合诊断脚本</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"><span class="token assign-left variable">OUTPUT_DIR</span><span class="token operator">=</span><span class="token variable">\${2<span class="token operator">:-</span><span class="token operator">/</span>tmp<span class="token operator">/</span>diagnostics}</span></span>
<span class="line"><span class="token assign-left variable">TIMESTAMP</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%Y%m%d-%H%M%S<span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$PID</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;用法: <span class="token variable">$0</span> &lt;PID&gt; [output-dir]&quot;</span></span>
<span class="line">    <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token function">mkdir</span> <span class="token parameter variable">-p</span> <span class="token variable">$OUTPUT_DIR</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 开始综合诊断 (进程: <span class="token variable">$PID</span>) ===&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;输出目录: <span class="token variable">$OUTPUT_DIR</span>&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 1. 基本信息</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 1. JVM 版本信息 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> VM.version <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/vm-version.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 命令行参数</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 2. JVM 命令行 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> VM.command_line <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/vm-command.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. JVM 标志</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 3. JVM 标志 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> VM.flags <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/vm-flags.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 4. 系统属性</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 4. 系统属性 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> VM.system_properties <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/vm-properties.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 5. 线程堆栈</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 5. 线程堆栈 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> Thread.print <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/thread-print.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 6. 堆转储</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 6. 堆转储 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> GC.heap_dump <span class="token assign-left variable">filename</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/heapdump-<span class="token variable">$TIMESTAMP</span>.hprof&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 7. 对象直方图</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 7. 对象直方图 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> GC.class_histogram <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/class-histo.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 8. 堆信息</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 8. 堆信息 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> GC.heap_info <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/heap-info.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 9. 性能计数器</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 9. 性能计数器 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> PerfCounter.print <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/perf-count.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 10. Finalizer 信息</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 10. Finalizer 信息 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> GC.finalizer_info <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>/finalizer-info.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 诊断完成 ===&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;所有文件保存在: <span class="token variable">$OUTPUT_DIR</span>&quot;</span></span>
<span class="line"><span class="token function">ls</span> <span class="token parameter variable">-la</span> <span class="token string">&quot;<span class="token variable">$OUTPUT_DIR</span>&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="自动化监控脚本" tabindex="-1"><a class="header-anchor" href="#自动化监控脚本"><span>自动化监控脚本</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># jcmd-monitor.sh - jcmd 监控脚本</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"><span class="token assign-left variable">INTERVAL</span><span class="token operator">=</span><span class="token variable">\${2<span class="token operator">:-</span>60}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$PID</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;用法: <span class="token variable">$0</span> &lt;PID&gt; [interval]&quot;</span></span>
<span class="line">    <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== jcmd 监控 (进程: <span class="token variable">$PID</span>) ===&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;监控间隔: <span class="token variable">\${INTERVAL}</span>秒&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">while</span> <span class="token boolean">true</span><span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">    <span class="token assign-left variable">TIMESTAMP</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> <span class="token string">&#39;+%Y-%m-%d %H:%M:%S&#39;</span><span class="token variable">)</span></span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;--- <span class="token variable">$TIMESTAMP</span> ---&quot;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment"># 堆信息</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 堆内存使用 ===&quot;</span></span>
<span class="line">    jcmd <span class="token variable">$PID</span> GC.heap_info</span>
<span class="line">    </span>
<span class="line">    <span class="token comment"># GC 统计</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;=== GC 统计 ===&quot;</span></span>
<span class="line">    jcmd <span class="token variable">$PID</span> GC.class_histogram <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-20</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment"># 线程数</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 线程统计 ===&quot;</span></span>
<span class="line">    jcmd <span class="token variable">$PID</span> Thread.print <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;^<span class="token entity" title="\\\\">\\\\</span><span class="token entity" title="\\&quot;">\\&quot;</span>&quot;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment"># Finalizer</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;=== Finalizer 状态 ===&quot;</span></span>
<span class="line">    jcmd <span class="token variable">$PID</span> GC.finalizer_info</span>
<span class="line">    </span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">    <span class="token function">sleep</span> <span class="token variable">$INTERVAL</span></span>
<span class="line"><span class="token keyword">done</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="故障排查脚本" tabindex="-1"><a class="header-anchor" href="#故障排查脚本"><span>故障排查脚本</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># jcmd-troubleshoot.sh - 故障排查脚本</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$PID</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;用法: <span class="token variable">$0</span> &lt;PID&gt;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== jcmd 故障排查 (进程: <span class="token variable">$PID</span>) ===&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 1. 检查进程状态</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 1. 进程状态 ---&quot;</span></span>
<span class="line"><span class="token function">ps</span> <span class="token parameter variable">-p</span> <span class="token variable">$PID</span> <span class="token parameter variable">-o</span> pid,ppid,cmd,%cpu,%mem,etime</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 线程分析</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 2. 线程分析 ---&quot;</span></span>
<span class="line"><span class="token assign-left variable">THREAD_COUNT</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>jcmd $PID Thread.print <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;^<span class="token entity" title="\\\\">\\\\</span><span class="token entity" title="\\&quot;">\\&quot;</span>&quot;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;线程总数: <span class="token variable">$THREAD_COUNT</span>&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">BLOCKED_COUNT</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>jcmd $PID Thread.print <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">grep</span> <span class="token string">&quot;BLOCKED&quot;</span> <span class="token operator">|</span> <span class="token function">wc</span> <span class="token parameter variable">-l</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;阻塞线程数: <span class="token variable">$BLOCKED_COUNT</span>&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. 内存分析</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 3. 内存分析 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> GC.heap_info</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 4. 对象统计</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 4. 对象统计 TOP 10 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> GC.class_histogram <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-15</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 5. 死锁检测</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 5. 死锁检测 ---&quot;</span></span>
<span class="line"><span class="token keyword">if</span> jcmd <span class="token variable">$PID</span> Thread.print <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-q</span> <span class="token string">&quot;deadlock&quot;</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;⚠️  检测到死锁!&quot;</span></span>
<span class="line">    jcmd <span class="token variable">$PID</span> Thread.print <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">30</span> <span class="token string">&quot;deadlock&quot;</span></span>
<span class="line"><span class="token keyword">else</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;✅ 未检测到死锁&quot;</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 6. JVM 配置</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 6. JVM 配置 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> VM.flags <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&quot;(HeapSize|GC|Trace)&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 7. 系统属性</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 7. 关键系统属性 ---&quot;</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> VM.system_properties <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&quot;(java.version|java.vendor|os.name|user.name)&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="与其他工具集成" tabindex="-1"><a class="header-anchor" href="#与其他工具集成"><span>与其他工具集成</span></a></h2><h3 id="工具生态系统概览" tabindex="-1"><a class="header-anchor" href="#工具生态系统概览"><span>工具生态系统概览</span></a></h3><p>现代 Java 应用监控通常通过以下工具链实现：</p><table><thead><tr><th>工具类型</th><th>工具名称</th><th>一句话介绍</th><th>关联关系</th></tr></thead><tbody><tr><td><strong>诊断采集</strong></td><td>jcmd</td><td>Java 官方进程诊断命令，提供全面的 JVM 内部状态信息</td><td>通过 jcmd/JMX 等工具从 Java 应用采集指标</td></tr><tr><td><strong>指标导出</strong></td><td>Micrometer</td><td>Java 指标库抽象层，提供统一的指标收集 API</td><td>通过 Micrometer 等工具标准化指标格式</td></tr><tr><td><strong>数据存储</strong></td><td>Prometheus</td><td>开源时序数据库，专为监控和告警设计，支持高维度标签查询</td><td>推送到 Prometheus 等时序数据库进行存储</td></tr><tr><td><strong>可视化</strong></td><td>Grafana</td><td>现代化的数据可视化平台，支持多种数据源和告警功能</td><td>在 Grafana 中配置数据源并创建 Dashboard 进行可视化与监控</td></tr></tbody></table><p><strong>典型集成流程</strong>： Java 应用 → jcmd/Micrometer → Prometheus → Grafana → 可视化与监控</p><h3 id="jcmd-prometheus-集成" tabindex="-1"><a class="header-anchor" href="#jcmd-prometheus-集成"><span>jcmd + Prometheus 集成</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># export-jcmd-metrics.sh - 导出 jcmd 指标到 Prometheus</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"><span class="token assign-left variable">OUTPUT_FILE</span><span class="token operator">=</span>/tmp/jcmd-metrics.prom</span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$PID</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;用法: <span class="token variable">$0</span> &lt;PID&gt;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 获取线程数</span></span>
<span class="line"><span class="token assign-left variable">THREAD_COUNT</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>jcmd $PID Thread.print <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;^<span class="token entity" title="\\\\">\\\\</span><span class="token entity" title="\\&quot;">\\&quot;</span>&quot;</span><span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 获取堆信息</span></span>
<span class="line"><span class="token assign-left variable">HEAP_INFO</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>jcmd $PID GC.heap_info <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null<span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">HEAP_USED</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$HEAP_INFO</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-oE</span> <span class="token string">&quot;used [0-9]+K&quot;</span> <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $2}&#39;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">HEAP_TOTAL</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$HEAP_INFO</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-oE</span> <span class="token string">&quot;total [0-9]+K&quot;</span> <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $2}&#39;</span><span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 获取性能计数器</span></span>
<span class="line"><span class="token assign-left variable">PERF_INFO</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>jcmd $PID PerfCounter.print <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null<span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">GC_COUNT</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$PERF_INFO</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token string">&quot;gc.total&quot;</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-1</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">GC_TIME</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$PERF_INFO</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token string">&quot;gc.total.time&quot;</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-1</span><span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 输出 Prometheus 格式</span></span>
<span class="line"><span class="token function">cat</span> <span class="token operator">&gt;</span> <span class="token variable">$OUTPUT_FILE</span> <span class="token operator">&lt;&lt;</span> <span class="token string">EOF</span>
<span class="line"># HELP jvm_threads_total Total number of threads</span>
<span class="line"># TYPE jvm_threads_total gauge</span>
<span class="line">jvm_threads_total <span class="token variable">$THREAD_COUNT</span></span>
<span class="line"># HELP jvm_heap_used_bytes Heap used bytes</span>
<span class="line"># TYPE jvm_heap_used_bytes gauge</span>
<span class="line">jvm_heap_used_bytes <span class="token variable">\${HEAP_USED<span class="token operator">:-</span>0}</span>000</span>
<span class="line"># HELP jvm_heap_total_bytes Heap total bytes</span>
<span class="line"># TYPE jvm_heap_total_bytes gauge</span>
<span class="line">jvm_heap_total_bytes <span class="token variable">\${HEAP_TOTAL<span class="token operator">:-</span>0}</span>000</span>
<span class="line"><span class="token variable">$GC_COUNT</span></span>
<span class="line"><span class="token variable">$GC_TIME</span></span>
<span class="line">EOF</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;指标已导出到 <span class="token variable">$OUTPUT_FILE</span>&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="jcmd-grafana-dashboard" tabindex="-1"><a class="header-anchor" href="#jcmd-grafana-dashboard"><span>jcmd + Grafana Dashboard</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;dashboard&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;JVM Diagnostic Metrics&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;panels&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Thread Count&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;graph&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;targets&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">          <span class="token punctuation">{</span></span>
<span class="line">            <span class="token property">&quot;expr&quot;</span><span class="token operator">:</span> <span class="token string">&quot;jvm_threads_total&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token property">&quot;legendFormat&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Total Threads&quot;</span></span>
<span class="line">          <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">]</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Heap Usage&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;graph&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;targets&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">          <span class="token punctuation">{</span></span>
<span class="line">            <span class="token property">&quot;expr&quot;</span><span class="token operator">:</span> <span class="token string">&quot;jvm_heap_used_bytes&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token property">&quot;legendFormat&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Heap Used&quot;</span></span>
<span class="line">          <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token punctuation">{</span></span>
<span class="line">            <span class="token property">&quot;expr&quot;</span><span class="token operator">:</span> <span class="token string">&quot;jvm_heap_total_bytes&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token property">&quot;legendFormat&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Heap Total&quot;</span></span>
<span class="line">          <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">]</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="jcmd-grafana-集成脚本" tabindex="-1"><a class="header-anchor" href="#jcmd-grafana-集成脚本"><span>jcmd + Grafana 集成脚本</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># update-grafana-metrics.sh - 更新 Grafana 指标</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PROMETHEUS_FILE</span><span class="token operator">=</span>/etc/prometheus/jvm-metrics.prom</span>
<span class="line"><span class="token assign-left variable">JCMD_PROM_FILE</span><span class="token operator">=</span>/tmp/jcmd-metrics.prom</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 导出 jcmd 指标</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token for-or-select variable">pid</span> <span class="token keyword">in</span> <span class="token variable"><span class="token variable">$(</span>jcmd <span class="token parameter variable">-l</span> <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span><span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">    ./export-jcmd-metrics.sh <span class="token variable">$pid</span> <span class="token operator">&gt;</span> <span class="token variable">$JCMD_PROM_FILE</span>-<span class="token variable">$pid</span>.prom</span>
<span class="line">    <span class="token function">cat</span> <span class="token variable">$JCMD_PROM_FILE</span>-<span class="token variable">$pid</span>.prom <span class="token operator">&gt;&gt;</span> <span class="token variable">$PROMETHEUS_FILE</span></span>
<span class="line"><span class="token keyword">done</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 重新加载 Prometheus 配置</span></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:9090/-/reload</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="性能影响与最佳实践" tabindex="-1"><a class="header-anchor" href="#性能影响与最佳实践"><span>性能影响与最佳实践</span></a></h2><h3 id="性能影响评估" tabindex="-1"><a class="header-anchor" href="#性能影响评估"><span>性能影响评估</span></a></h3><p>jcmd 命令的性能影响因命令类型而异：</p><table><thead><tr><th>命令</th><th>CPU 开销</th><th>性能影响核心风险</th><th>推荐场景</th></tr></thead><tbody><tr><td>VM.flags</td><td>极低</td><td>几乎无风险，不暂停应用线程。</td><td>可随时安全执行，用于配置检查</td></tr><tr><td>Thread.print</td><td>触发全局暂停（STW）。对高并发、低延迟应用影响显著。</td><td>100ms-2s</td><td>常规分析，避免在高并发业务高峰期执行。</td></tr><tr><td>GC.class_histogram</td><td>中高</td><td>长时间全局暂停，可能导致秒级甚至更长的服务中断。</td><td>仅在业务低峰期或预发环境使用，用于分析内存对象分布。</td></tr><tr><td>GC.heap_dump</td><td>高</td><td>极高风险的运维操作，可能造成生产服务长时间不可用。</td><td>视为最后手段，仅在严重内存故障时使用，并提前规划维护窗口。</td></tr><tr><td>GC.run</td><td>高</td><td>完全STW，停顿时间和影响视 GC 而定</td><td>生产环境通常应避免，除非在明确、受控的调优场景下。</td></tr></tbody></table><h3 id="最佳实践建议" tabindex="-1"><a class="header-anchor" href="#最佳实践建议"><span>最佳实践建议</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 生产环境最佳实践</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 1. 常规监控使用轻量级命令</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> VM.flags                    <span class="token comment"># 查看配置</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> VM.version                  <span class="token comment"># 查看版本</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> PerfCounter.print <span class="token operator">|</span> <span class="token function">grep</span> gc <span class="token comment"># GC 统计</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 故障排查使用完整命令</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> Thread.print <span class="token operator">&gt;</span> threaddump.txt</span>
<span class="line">jcmd <span class="token variable">$PID</span> GC.heap_dump <span class="token assign-left variable">filename</span><span class="token operator">=</span>heapdump.hprof</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. 低峰期执行重量级操作</span></span>
<span class="line"><span class="token comment"># 使用 cron 定时任务</span></span>
<span class="line"><span class="token number">0</span> <span class="token number">3</span> * * * /opt/scripts/jcmd-diagnostic.sh <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 4. 限制操作频率</span></span>
<span class="line"><span class="token comment"># 避免过于频繁的堆转储</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 5. 自动化分析流程</span></span>
<span class="line"><span class="token comment"># 使用脚本自动执行诊断命令</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="常见问题排查" tabindex="-1"><a class="header-anchor" href="#常见问题排查"><span>常见问题排查</span></a></h3><p><strong>问题 1：jcmd 连接失败</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 检查进程是否存在</span></span>
<span class="line">jcmd <span class="token parameter variable">-l</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 检查用户权限</span></span>
<span class="line"><span class="token function">ps</span> <span class="token parameter variable">-ef</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token function">java</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用相同用户执行</span></span>
<span class="line"><span class="token function">sudo</span> <span class="token parameter variable">-u</span> <span class="token operator">&lt;</span>user<span class="token operator">&gt;</span> jcmd <span class="token variable">$PID</span> <span class="token builtin class-name">help</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 检查 JDK 版本兼容性</span></span>
<span class="line"><span class="token function">java</span> <span class="token parameter variable">-version</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>问题 2：诊断命令执行超时</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 增加超时时间</span></span>
<span class="line"><span class="token function">timeout</span> <span class="token number">30</span> jcmd <span class="token variable">$PID</span> Thread.print</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用 -l 参数减少输出</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> Thread.print <span class="token parameter variable">-l</span><span class="token operator">=</span>false</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>问题 3：生成堆转储失败</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 检查磁盘空间</span></span>
<span class="line"><span class="token function">df</span> <span class="token parameter variable">-h</span> /data</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 检查文件权限</span></span>
<span class="line"><span class="token function">ls</span> <span class="token parameter variable">-la</span> /data/</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用其他目录</span></span>
<span class="line">jcmd <span class="token variable">$PID</span> GC.heap_dump <span class="token assign-left variable">filename</span><span class="token operator">=</span>/tmp/heapdump.hprof</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="扩展功能" tabindex="-1"><a class="header-anchor" href="#扩展功能"><span>扩展功能</span></a></h2><h3 id="自定义诊断命令" tabindex="-1"><a class="header-anchor" href="#自定义诊断命令"><span>自定义诊断命令</span></a></h3><p>JVM 支持通过 JVMTI 和诊断命令框架添加自定义诊断命令：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 示例：自定义诊断命令实现</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token import"><span class="token namespace">sun<span class="token punctuation">.</span>management<span class="token punctuation">.</span></span><span class="token class-name">ManagementFactory</span></span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>sun<span class="token punctuation">.</span>management<span class="token punctuation">.</span></span><span class="token class-name">HotSpotDiagnosticMXBean</span></span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">CustomDiagnostic</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">String</span> <span class="token constant">COMMAND_NAME</span> <span class="token operator">=</span> <span class="token string">&quot;custom.diagnostic&quot;</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 注册自定义命令</span></span>
<span class="line">        <span class="token comment">// 需要通过 -XX:+UnlockDiagnosticVMOptions 启用</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="远程诊断配置" tabindex="-1"><a class="header-anchor" href="#远程诊断配置"><span>远程诊断配置</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 启用远程诊断：开启JMX远程管理功能，允许外部工具（如JConsole、VisualVM、JMC等）通过网络连接到该JVM进程，进行监控和管理。</span></span>
<span class="line"><span class="token function">java</span> <span class="token parameter variable">-Dcom.sun.management.jmxremote.port</span><span class="token operator">=</span><span class="token number">9010</span> <span class="token punctuation">\\</span></span>
<span class="line">     <span class="token parameter variable">-Dcom.sun.management.jmxremote.ssl</span><span class="token operator">=</span>false <span class="token punctuation">\\</span></span>
<span class="line">     <span class="token parameter variable">-Dcom.sun.management.jmxremote.authenticate</span><span class="token operator">=</span>false <span class="token punctuation">\\</span></span>
<span class="line">     <span class="token parameter variable">-jar</span> application.jar</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用 jcmd 远程诊断</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>remote-pid<span class="token operator">&gt;</span> <span class="token operator">&lt;</span>command<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="常用命令速查表" tabindex="-1"><a class="header-anchor" href="#常用命令速查表"><span>常用命令速查表</span></a></h2><h3 id="基础诊断命令" tabindex="-1"><a class="header-anchor" href="#基础诊断命令"><span>基础诊断命令</span></a></h3><table><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>VM.version</code></td><td>JVM 版本</td><td><code>jcmd &lt;PID&gt; VM.version</code></td></tr><tr><td><code>VM.flags</code></td><td>JVM 参数</td><td><code>jcmd &lt;PID&gt; VM.flags</code></td></tr><tr><td><code>VM.system_properties</code></td><td>系统属性</td><td><code>jcmd &lt;PID&gt; VM.system_properties</code></td></tr><tr><td><code>VM.command_line</code></td><td>命令行参数</td><td><code>jcmd &lt;PID&gt; VM.command_line</code></td></tr></tbody></table><h3 id="线程分析命令" tabindex="-1"><a class="header-anchor" href="#线程分析命令"><span>线程分析命令</span></a></h3><table><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>Thread.print</code></td><td>线程堆栈</td><td><code>jcmd &lt;PID&gt; Thread.print -l=true</code></td></tr></tbody></table><h3 id="内存分析命令" tabindex="-1"><a class="header-anchor" href="#内存分析命令"><span>内存分析命令</span></a></h3><table><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>GC.heap_dump</code></td><td>堆转储</td><td><code>jcmd &lt;PID&gt; GC.heap_dump filename=x.hprof</code></td></tr><tr><td><code>GC.heap_info</code></td><td>堆信息</td><td><code>jcmd &lt;PID&gt; GC.heap_info</code></td></tr><tr><td><code>GC.class_histogram</code></td><td>对象直方图</td><td><code>jcmd &lt;PID&gt; GC.class_histogram</code></td></tr><tr><td><code>GC.run</code></td><td>执行 GC</td><td><code>jcmd &lt;PID&gt; GC.run</code></td></tr><tr><td><code>GC.finalizer_info</code></td><td>Finalizer 信息</td><td><code>jcmd &lt;PID&gt; GC.finalizer_info</code></td></tr></tbody></table><h3 id="性能监控命令" tabindex="-1"><a class="header-anchor" href="#性能监控命令"><span>性能监控命令</span></a></h3><table><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>PerfCounter.print</code></td><td>性能计数器</td><td><code>jcmd &lt;PID&gt; PerfCounter.print</code></td></tr><tr><td><code>JVMTM.data_dump</code></td><td>JVMTI 数据</td><td><code>jcmd &lt;PID&gt; JVMTM.data_dump</code></td></tr></tbody></table><h2 id="常见问题-faq" tabindex="-1"><a class="header-anchor" href="#常见问题-faq"><span>常见问题 FAQ</span></a></h2><h3 id="q1-jcmd-和-jstack-jmap-的区别" tabindex="-1"><a class="header-anchor" href="#q1-jcmd-和-jstack-jmap-的区别"><span>Q1：jcmd 和 jstack/jmap 的区别？</span></a></h3><p><strong>jcmd</strong> 优势：</p><ul><li>统一的诊断接口</li><li>更稳定的连接方式</li><li>更多的诊断命令</li><li>支持远程诊断</li></ul><p><strong>独立工具</strong> 优势：</p><ul><li>更轻量</li><li>特定的优化功能</li><li>熟悉的使用方式</li></ul><p><strong>建议</strong>：日常使用 jcmd，特殊场景使用独立工具。</p><h3 id="q2-如何诊断无响应的-jvm" tabindex="-1"><a class="header-anchor" href="#q2-如何诊断无响应的-jvm"><span>Q2：如何诊断无响应的 JVM？</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 1. 检查线程状态</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> Thread.print</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 查看系统属性</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.system_properties</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. 生成堆转储</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> GC.heap_dump <span class="token assign-left variable">filename</span><span class="token operator">=</span>heapdump.hprof</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 4. 查看性能计数器</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> PerfCounter.print</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="q3-jcmd-支持多少诊断命令" tabindex="-1"><a class="header-anchor" href="#q3-jcmd-支持多少诊断命令"><span>Q3：jcmd 支持多少诊断命令？</span></a></h3><p>数量因 JVM 版本而异，可通过以下命令查看：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 列出所有可用命令</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token builtin class-name">help</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查看特定分类的命令</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token builtin class-name">help</span> <span class="token operator">|</span> <span class="token function">grep</span> GC</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="q4-如何提高-jcmd-的可靠性" tabindex="-1"><a class="header-anchor" href="#q4-如何提高-jcmd-的可靠性"><span>Q4：如何提高 jcmd 的可靠性？</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 1. 使用最新版本的 JDK</span></span>
<span class="line"><span class="token function">java</span> <span class="token parameter variable">-version</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 增加 JVM 启动参数</span></span>
<span class="line"><span class="token parameter variable">-XX:+UnlockDiagnosticVMOptions</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="q5-jcmd-可以用于生产环境吗" tabindex="-1"><a class="header-anchor" href="#q5-jcmd-可以用于生产环境吗"><span>Q5：jcmd 可以用于生产环境吗？</span></a></h3><p>可以，但需要注意：</p><table><thead><tr><th>操作</th><th>生产环境建议</th></tr></thead><tbody><tr><td><code>VM.flags</code></td><td>✅ 安全，读取操作</td></tr><tr><td><code>Thread.print</code></td><td>✅ 安全，可定期执行</td></tr><tr><td><code>PerfCounter.print</code></td><td>✅ 安全，读取操作</td></tr><tr><td><code>GC.heap_dump</code></td><td>⚠️ 谨慎，生成大文件</td></tr><tr><td><code>GC.run</code></td><td>⚠️ 谨慎，可能触发 Full GC</td></tr></tbody></table><h2 id="相关资源" tabindex="-1"><a class="header-anchor" href="#相关资源"><span>相关资源</span></a></h2><h3 id="官方文档" tabindex="-1"><a class="header-anchor" href="#官方文档"><span>官方文档</span></a></h3><ul><li><a href="https://docs.oracle.com/en/java/javase/17/docs/specs/man/jcmd.html" target="_blank" rel="noopener noreferrer">jcmd 官方文档</a></li><li><a href="https://docs.oracle.com/javase/8/docs/technotes/guides/troubleshoot/tooldescr007.html" target="_blank" rel="noopener noreferrer">JVM 诊断命令参考</a></li></ul><h3 id="分析工具" tabindex="-1"><a class="header-anchor" href="#分析工具"><span>分析工具</span></a></h3><ul><li><a href="https://eclipse.dev/mat/" target="_blank" rel="noopener noreferrer">Eclipse Memory Analyzer</a></li><li><a href="https://fastthread.io/" target="_blank" rel="noopener noreferrer">FastThread</a></li><li><a href="https://gceasy.io/" target="_blank" rel="noopener noreferrer">GCEasy</a></li></ul><h3 id="性能优化参考" tabindex="-1"><a class="header-anchor" href="#性能优化参考"><span>性能优化参考</span></a></h3><ul><li><a href="https://docs.oracle.com/en/java/javase/17/perform/" target="_blank" rel="noopener noreferrer">Oracle JVM 诊断指南</a></li><li><a href="https://docs.oracle.com/javase/8/docs/technotes/guides/vm/performance-enhancements-7.html" target="_blank" rel="noopener noreferrer">JVM Performance Tuning</a></li></ul><h3 id="社区资源" tabindex="-1"><a class="header-anchor" href="#社区资源"><span>社区资源</span></a></h3><ul><li><a href="https://stackoverflow.com/questions/tagged/jcmd" target="_blank" rel="noopener noreferrer">Stack Overflow - jcmd</a></li><li><a href="https://github.com/topics/jvm-diagnostics" target="_blank" rel="noopener noreferrer">GitHub - JVM 诊断工具</a></li></ul>`,141)]))}const o=n(p,[["render",i]]),r=JSON.parse('{"path":"/java/advanced/diagnostic-tools/diagnostic-jcmd.html","title":"jcmd - JVM 诊断命令行工具","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1767688846000,"contributors":[{"name":"zhaomy","username":"zhaomy","email":"3036190149@qq.com","commits":1,"url":"https://github.com/zhaomy"}],"changelog":[{"hash":"002042d6ccab469ab518aca6e5eb5ee2c566721e","time":1767688846000,"email":"3036190149@qq.com","author":"zhaomy","message":"docs: 新增Java诊断与监控工具相关文档"}]},"filePathRelative":"java/advanced/diagnostic-tools/diagnostic-jcmd.md","excerpt":"\\n<p>jcmd（JVM Command）是 JDK 7u40 引入的综合诊断命令行工具，提供对 JVM 进行多种诊断操作的能力。它整合了多个诊断工具的功能，可以通过一个统一的接口执行 JVM 诊断、监控和故障排查任务，是 JDK 中功能最全面的诊断命令行工具。</p>\\n<h2>工具概述</h2>\\n<p>jcmd 通过 JVM 的诊断命令接口（Diagnostic Command Interface）与目标 JVM 进程通信，支持执行预定义的诊断命令、获取系统属性、查看线程堆栈、生成堆转储、执行 GC 等操作。相比单独的诊断工具，jcmd 提供了更统一、更可靠的诊断能力。</p>\\n<p><strong>工具特点</strong>：</p>"}');export{o as comp,r as data};
